import os, re, base64, zlib
R="LockCOC" if os.path.isdir("LockCOC") else "."
def P(p): return os.path.join(R,p)
def rd(p): return open(P(p),encoding="utf-8").read()
def w(p,s,m="w"): open(P(p),m,encoding="utf-8").write(s)
F={'srv.py': '', 'chatplus.js': '', 'chat.css': ''}
def D(k): return zlib.decompress(base64.b64decode(F[k])).decode("utf-8")
def sub(s,old,new,what):
    if old not in s: raise SystemExit("[loi] khong thay doan can sua: "+what)
    return s.replace(old,new,1)
a=rd("app.py")
if "_norm_fs" in a: raise SystemExit("[loi] da ap dung patch24 roi")
pat=re.compile(r'@app\.(?:get|post)\("/api/chat/(?:messages/<other_uid>|send|read)"\)\n@api\ndef chat_\w+\(.*?\):\n.*?\n\n\n',re.S)
a,n=pat.subn("",a)
if n!=3: raise SystemExit("[loi] khong go duoc 3 ham chat cu (tim thay %d)"%n)
a=sub(a,'@app.get("/library")',D("srv.py")+"\n\n@app.get(\"/library\")","route library")
w("app.py",a)
w("static/js/chatplus.js",D("chatplus.js"))
c=rd("static/polish.css")
if ".m-wrap" not in c: w("static/polish.css",c+"\n"+D("chat.css"))
